import test from 'node:test';
import assert from 'node:assert/strict';
import { planKitchenLayout, evaluateKitchenConstraints, KITCHEN_MODULE_LIBRARY } from '../packages/engineering-engine/src/index.js';
test('selects production corner strategy for L kitchen', () => { const p = planKitchenLayout({ layoutId: 'c1', kind: 'l_shape', roomWidthMm: 4200, roomDepthMm: 3200 }); const r = evaluateKitchenConstraints(p, { corners: [{ at: 'south_east' }] }); assert.equal(r.ready, true); assert.equal(r.corners[0]?.libraryModuleId, 'corner.base.carousel'); });
test('blocks radiator collision with south run', () => { const p = planKitchenLayout({ layoutId: 'c2', kind: 'straight', roomWidthMm: 3600, roomDepthMm: 2800 }); const r = evaluateKitchenConstraints(p, { obstacles: [{ id: 'rad1', kind: 'radiator', xMm: 900, yMm: 0, widthMm: 800, depthMm: 200, clearanceMm: 100 }] }); assert.equal(r.ready, false); assert.ok(r.issues.some(i => i.code === 'OBSTACLE_COLLISION')); });
test('blocks door opening swing zone', () => { const p = planKitchenLayout({ layoutId: 'c3', kind: 'straight', roomWidthMm: 3600, roomDepthMm: 2800 }); const r = evaluateKitchenConstraints(p, { openingZones: [{ id: 'door-swing', owner: 'door', xMm: 0, yMm: 0, widthMm: 900, depthMm: 900 }] }); assert.equal(r.ready, false); assert.ok(r.issues.some(i => i.code === 'OPENING_ZONE_COLLISION')); });
test('corner library has blind carousel LeMans and diagonal variants', () => { for (const id of ['corner.base.blind', 'corner.base.carousel', 'corner.base.lemans', 'corner.base.diagonal'])
    assert.ok(KITCHEN_MODULE_LIBRARY[id]); });
